window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-eaa10cd5e1a21ceb"]={"versions": [{"id": "FIG-eaa10cd5e1a21ceb", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Release R3.0.7).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell. Das Diagramm spezifiziert die Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie (Cluster, ECUs, Gateways) und Kommunikationsmatrix (Frames, PDUs, Signale), die ursprünglich aus dem FIBEX-Standard (ASAM) in die AUTOSAR-System-Description (ARXML) überführt wurden.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>SystemTemplate::System</code>: Repräsentiert die Gesamtsystem-Beschreibung. Trägt das Stereotyp <code>«atpStructureElement»</code> und spezialisiert <code>ARElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> (0..n) Instanzen der Metaklasse <code>FibexElement</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>PackageableElement::FibexElement</code>: Abstrakte Metaklasse (Generalisierung von <code>PackageableElement</code>), dient als einheitliche Wurzel für alle bus- und kommunikationsspezifischen Artefakte.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code> (Topologie &amp; Kommunikation):</strong>\n<ul class=\"fig-list\"><li><code>CoreTopology::CommunicationCluster</code>: Repräsentiert das physikalische Netzwerk bzw. den Kommunikationskanal (z. B. CAN-, LIN-, FlexRay-Cluster).\n</li><li><code>CoreTopology::EcuInstance</code>: Physische Steuergeräte-Instanz innerhalb der Topologie.\n</li><li><code>Fibex4Multiplatform::Gateway</code>: Modelliert Gateway-Funktionalität. Besitzt eine gerichtete Assoziation <code>+ecu</code> mit Kardinalität <code>1</code> zu <code>CoreTopology::EcuInstance</code> (ein Gateway ist strikt genau einem physikalischen Steuergerät zugeordnet).\n</li><li><code>CoreCommunication::Frame</code>: Protokollrahmen auf dem Übertragungsmedium (L2-Frame).\n</li><li><code>CoreCommunication::ISignal</code>: Interaktionssignal / Anwendungsdatum (Payload-Signal auf Systemebene).\n</li><li><code>CoreCommunication::IPduGroup</code>: Logische Bündelung von I-PDUs zur gemeinsamen Laufzeitsteuerung.\n</li><li><code>CoreCommunication::Pdu</code>: Abstrakte Basisklasse für alle Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>CoreCommunication::Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>CoreCommunication::NmPdu</code>: Spezialisierte PDU für Netzwerkmanagement (NM-Stack).\n</li><li><code>CoreCommunication::IPdu</code>: Interaktions-Layer-PDU (kapselt Signale für den AUTOSAR COM-Stack).\n</li><li><code>CoreCommunication::NPdu</code>: Netzwerk-/Transport-PDU, spezialisiert <code>CoreCommunication::IPdu</code> (Einsatz im Kontext von Transportprotokollen wie CanTp/FrTp zur Übertragung segmentierter Großnachrichten).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li>Ein System-Toolchain-Importer löst die <code>System</code> → <code>FibexElement</code>-Referenzen auf, extrahiert die <code>EcuInstance</code> und generiert den <em>ECU Extract of System Description</em>.\n</li><li>Die Zuordnung <code>Gateway</code> → <code>EcuInstance</code> erzeugt die Routing-Tabellen für den PDU-Router (<code>PduR</code>).\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><strong>PDU-Steuerung:</strong> <code>IPduGroup</code> definiert die Gruppenmasken für die Aktivierung/Deaktivierung der zyklischen PDU-Übertragung (<code>Com_IpduGroupStart()</code>, <code>Com_IpduGroupStop()</code>).\n</li><li><strong>Transport vs. Direktpfad:</strong> <code>NPdu</code> signalisiert dem PduR die Einbindung des Transportprotokolls (<code>&lt;Bus&gt;Tp</code>), während Standard-<code>IPdu</code> direkt zwischen Interface-Modul (<code>&lt;Bus&gt;If</code>) und <code>Com</code> geroutet wird.\n</li><li><strong>Netzwerkstatus:</strong> <code>NmPdu</code> triggert Rx/Tx-Indikationen im Bus-NM (<code>CanNm</code>, <code>FrNm</code>), welche die Busruhe und Wakeup-Zyklen steuern.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Com-Stack):</strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanzen von <code>IPdu</code> und <code>ISignal</code> fließen direkt in die Konfiguration von <code>Com</code> (<code>ComIPdu</code>, <code>ComSignal</code>) und <code>PduR</code> (<code>PduRRoutingPath</code>) ein.\n</li><li>Bitversätze, Signal-Layouts und Endianness aus <code>ISignal</code> bestimmen das Packen/Entpacken im AUTOSAR COM (<code>Com_SendSignal()</code>, <code>Com_ReceiveSignal()</code>).\n</li></ul>\n</li><li><strong>Kardinalitäts-Restriktion <code>+ecu: 1</code> am <code>Gateway</code>:</strong>\n<ul class=\"fig-list\"><li>Routing-Beziehungen können nicht virtuell „im Netz“ schweben; sie müssen immer zwingend einer realen ECU-Instanz zugeordnet sein. Im Codegenerator führt ein ungebundenes Gateway zu fatalen Validierungsfehlern.\n</li></ul>\n</li><li><strong>Architektur-Einschränkung in R3.0.7:</strong>\n<ul class=\"fig-list\"><li>Die Modellierung von <code>NPdu</code> als Subklasse von <code>IPdu</code> reflektiert die frühe AUTOSAR-Architektur. Entwickler müssen beachten, dass TP-PDUs und reguläre I-PDUs im System-Template eng gekoppelt sind, bevor in späteren Releases (ab 4.x) eine stärkere Trennung in <code>ISignalIPdu</code>, <code>SecuredIPdu</code> und generische PDU-Transformationen erfolgte.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-11e7a92424a73887", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Release R3.0.7).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell. Das Diagramm spezifiziert die Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie (Cluster, ECUs, Gateways) und Kommunikationsmatrix (Frames, PDUs, Signale), die ursprünglich aus dem FIBEX-Standard (ASAM) in die AUTOSAR-System-Description (ARXML) überführt wurden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>SystemTemplate::System</code>: Repräsentiert die Gesamtsystem-Beschreibung. Trägt das Stereotyp <code>«atpStructureElement»</code> und spezialisiert <code>ARElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> (0..n) Instanzen der Metaklasse <code>FibexElement</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>PackageableElement::FibexElement</code>: Abstrakte Metaklasse (Generalisierung von <code>PackageableElement</code>), dient als einheitliche Wurzel für alle bus- und kommunikationsspezifischen Artefakte.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code> (Topologie &amp; Kommunikation):</strong>\n<ul class=\"fig-list\"><li><code>CoreTopology::CommunicationCluster</code>: Repräsentiert das physikalische Netzwerk bzw. den Kommunikationskanal (z. B. CAN-, LIN-, FlexRay-Cluster).\n</li><li><code>CoreTopology::EcuInstance</code>: Physische Steuergeräte-Instanz innerhalb der Topologie.\n</li><li><code>Fibex4Multiplatform::Gateway</code>: Modelliert Gateway-Funktionalität. Besitzt eine gerichtete Assoziation <code>+ecu</code> mit Kardinalität <code>1</code> zu <code>CoreTopology::EcuInstance</code> (ein Gateway ist strikt genau einem physikalischen Steuergerät zugeordnet).\n</li><li><code>CoreCommunication::Frame</code>: Protokollrahmen auf dem Übertragungsmedium (L2-Frame).\n</li><li><code>CoreCommunication::ISignal</code>: Interaktionssignal / Anwendungsdatum (Payload-Signal auf Systemebene).\n</li><li><code>CoreCommunication::IPduGroup</code>: Logische Bündelung von I-PDUs zur gemeinsamen Laufzeitsteuerung.\n</li><li><code>CoreCommunication::Pdu</code>: Abstrakte Basisklasse für alle Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>CoreCommunication::Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>CoreCommunication::NmPdu</code>: Spezialisierte PDU für Netzwerkmanagement (NM-Stack).\n</li><li><code>CoreCommunication::IPdu</code>: Interaktions-Layer-PDU (kapselt Signale für den AUTOSAR COM-Stack).\n</li><li><code>CoreCommunication::NPdu</code>: Netzwerk-/Transport-PDU, spezialisiert <code>CoreCommunication::IPdu</code> (Einsatz im Kontext von Transportprotokollen wie CanTp/FrTp zur Übertragung segmentierter Großnachrichten).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li>Ein System-Toolchain-Importer löst die <code>System</code> → <code>FibexElement</code>-Referenzen auf, extrahiert die <code>EcuInstance</code> und generiert den <em>ECU Extract of System Description</em>.\n</li><li>Die Zuordnung <code>Gateway</code> → <code>EcuInstance</code> erzeugt die Routing-Tabellen für den PDU-Router (<code>PduR</code>).\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><strong>PDU-Steuerung:</strong> <code>IPduGroup</code> definiert die Gruppenmasken für die Aktivierung/Deaktivierung der zyklischen PDU-Übertragung (<code>Com_IpduGroupStart()</code>, <code>Com_IpduGroupStop()</code>).\n</li><li><strong>Transport vs. Direktpfad:</strong> <code>NPdu</code> signalisiert dem PduR die Einbindung des Transportprotokolls (<code>&lt;Bus&gt;Tp</code>), während Standard-<code>IPdu</code> direkt zwischen Interface-Modul (<code>&lt;Bus&gt;If</code>) und <code>Com</code> geroutet wird.\n</li><li><strong>Netzwerkstatus:</strong> <code>NmPdu</code> triggert Rx/Tx-Indikationen im Bus-NM (<code>CanNm</code>, <code>FrNm</code>), welche die Busruhe und Wakeup-Zyklen steuern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Com-Stack):</strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanzen von <code>IPdu</code> und <code>ISignal</code> fließen direkt in die Konfiguration von <code>Com</code> (<code>ComIPdu</code>, <code>ComSignal</code>) und <code>PduR</code> (<code>PduRRoutingPath</code>) ein.\n</li><li>Bitversätze, Signal-Layouts und Endianness aus <code>ISignal</code> bestimmen das Packen/Entpacken im AUTOSAR COM (<code>Com_SendSignal()</code>, <code>Com_ReceiveSignal()</code>).\n</li></ul>\n</li><li><strong>Kardinalitäts-Restriktion <code>+ecu: 1</code> am <code>Gateway</code>:</strong>\n<ul class=\"fig-list\"><li>Routing-Beziehungen können nicht virtuell „im Netz“ schweben; sie müssen immer zwingend einer realen ECU-Instanz zugeordnet sein. Im Codegenerator führt ein ungebundenes Gateway zu fatalen Validierungsfehlern.\n</li></ul>\n</li><li><strong>Architektur-Einschränkung in R3.0.7:</strong>\n<ul class=\"fig-list\"><li>Die Modellierung von <code>NPdu</code> als Subklasse von <code>IPdu</code> reflektiert die frühe AUTOSAR-Architektur. Entwickler müssen beachten, dass TP-PDUs und reguläre I-PDUs im System-Template eng gekoppelt sind, bevor in späteren Releases (ab 4.x) eine stärkere Trennung in <code>ISignalIPdu</code>, <code>SecuredIPdu</code> und generische PDU-Transformationen erfolgte.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-426867045b6d6465", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Release R3.2.3).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell. Das Diagramm spezifiziert die Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie (Cluster, ECUs, Gateways) und Kommunikationsmatrix (Frames, PDUs, Signale, Routing-Gruppen).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>SystemTemplate::System</code>: Repräsentiert die Gesamtsystem-Beschreibung. Trägt das Stereotyp <code>«atpStructureElement»</code> und spezialisiert <code>ARElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> (0..n) Instanzen der Metaklasse <code>FibexElement</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>PackageableElement::FibexElement</code>: Abstrakte Metaklasse (Generalisierung von <code>PackageableElement</code>), dient als einheitliche Wurzel für alle bus- und kommunikationsspezifischen Artefakte.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CoreTopology::CommunicationCluster</code>: Repräsentiert das physikalische Netzwerk bzw. den Kommunikationskanal.\n</li><li><code>CoreTopology::EcuInstance</code>: Physische Steuergeräte-Instanz innerhalb der Topologie.\n</li><li><code>Fibex4Multiplatform::Gateway</code>: Modelliert Gateway-Funktionalität als eigenständiges Topologie-/Routing-Element.\n</li><li><code>CoreCommunication::ISignal</code>: Interaktionssignal / Anwendungsdatum auf Systemebene.\n</li><li><code>CoreCommunication::IPduGroup</code>: Logische Bündelung von I-PDUs zur Steuerung im COM-Stack.\n</li><li><code>CoreCommunication::PdurIPduGroup</code>: Logische Gruppierung von PDUs zur Laufzeit-Aktivierung/Deaktivierung im PDU-Router (<code>PduR</code>).\n</li><li><code>CoreCommunication::Frame</code>: Protokollrahmen auf dem Übertragungsmedium (L2-Frame).\n</li><li><code>CoreCommunication::Pdu</code>: Metaklasse für Protocol Data Units ohne abgebildete Subklassen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li>System-Tools lösen die <code>System</code> → <code>FibexElement</code>-Referenzen auf, um den <em>ECU Extract of System Description</em> für einzelne Steuergeräte abzuleiten.\n</li><li><code>PdurIPduGroup</code> ermöglicht Toolchains die Konfiguration getrennter Routing-Tabellen und Routing-Pfade im PDU-Router.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><strong>PDU- und Routing-Steuerung:</strong> <code>IPduGroup</code> steuert die Aktivierung zyklischer I-PDUs im AUTOSAR COM (<code>Com_IpduGroupStart()</code>, <code>Com_IpduGroupStop()</code>). <code>PdurIPduGroup</code> ermöglicht das gezielte Aktivieren und Deaktivieren ganzer PDU-Routing-Pfade direkt im <code>PduR</code> (<code>PduR_EnableRouting()</code>, <code>PduR_DisableRouting()</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Alle abgebildeten Spezialisierungen von <code>FibexElement</code> sind vollwertige Packageable Elements und können modular in <code>AR-PACKAGE</code>-Containern abgelegt werden.\n</li><li><code>PdurIPduGroup</code> und <code>IPduGroup</code> existieren als parallele Metaklassen zur Trennung von COM-Gruppensteuerung und PduR-Routingsteuerung.\n</li><li><code>Gateway</code> besitzt keine direkte 1:1-Assoziationslinie zu <code>EcuInstance</code> im Diagramm.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2968debec6b6a537", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Release R4.0.3).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung, Netzwerkmanagement- und Transportprotokoll-Konfigurationen sowie PDU-Typen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>SystemTemplate::System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation»</code> mit dem Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexCore::FibexElement</code>: Abstrakte Metaklasse im Paket <code>FibexCore</code>, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CoreTopology::CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, annotiert mit <code>«atpVariation»</code> (variantenfähig).\n</li><li><code>CoreTopology::EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Fibex4Multiplatform::Gateway</code>: Gateway-Definition.\n</li><li><code>CoreCommunication::ISignalIPduGroup</code>: Zusammenfassung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>CoreCommunication::PdurIPduGroup</code>: Gruppierung von PduR-Routingpfaden.\n</li><li><code>CoreCommunication::ISignal</code>: Interaktionssignal auf Systemebene.\n</li><li><code>CoreCommunication::ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale (z. B. zur Gewährleistung atomarer Konsistenz).\n</li><li><code>CoreCommunication::Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NetworkManagement::NmConfig</code>: Zentrale Konfiguration des Netzwerkmanagements für das System.\n</li><li><code>TransportProtocols::TpConfig</code>: Konfiguration von Transportprotokollen (z. B. CanTp, FrTp, DoIP).\n</li><li><code>CoreCommunication::Pdu</code>: Abstrakte Basisklasse für Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>CoreCommunication::Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>CoreCommunication::IPdu</code>: Interaktions-PDU zur Signalübertragung im COM-Stack.\n</li><li><code>CoreCommunication::NmPdu</code>: Netzwerkmanagement-PDU.\n</li><li><code>CoreCommunication::XcpPdu</code>: Spezialisierte PDU für Mess-, Kalibrier- und Diagnoseprotokolle via XCP.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Durch <code>«atpVariation»</code> an <code>+fibexElement</code> (mit <code>Vh.latestBindingTime = PostBuild</code>) und an <code>CommunicationCluster</code> können Netzwerktopologie und Kommunikationsmatrizen variantenabhängig konfiguriert und bis zum Post-Build-Zeitpunkt gebunden werden.\n</li><li><strong>Konfigurationsgenerierung:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die systemweiten Vorgaben für die Codegenerierung der BSW-Stacks <code>Nm</code>/<code>&lt;Bus&gt;Nm</code> sowie der TP-Module (<code>CanTp</code>, <code>FrTp</code> etc.).\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> dient der selektiven Freigabe von I-PDUs im COM-Modul.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Pfade im PDU-Router um.\n</li><li><code>XcpPdu</code> wird vom PduR direkt an das XCP-Modul (XcpOnCan, XcpOnFr, XcpOnEth) weitergeleitet, unter Umgehung des AUTOSAR COM-Stacks.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Die Assoziation <code>+fibexElement</code> unterstützt Variantenmechanismen (<code>&lt;VARIATION-POINT&gt;</code>), wodurch einzelne Kommunikationselemente erst nach der Systemgenerierung (Post-Build) final aktiviert oder deaktiviert werden können.\n</li><li><code>ISignalGroup</code> stellt metamodell-seitig sicher, dass Signalgruppen für konsistente Signal-Shadow-Buffer-Updates in COM definiert werden.\n</li><li><code>NmConfig</code> und <code>TpConfig</code> sind als eigenständige <code>FibexElement</code>-Klassen im Systemmodell verankert und referenzierbar.\n</li><li><code>XcpPdu</code> existiert als direkte Spezialisierung von <code>Pdu</code>.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2be62dd9be2e7bfa", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Release R4.1.3).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung, Netzwerkmanagement- und Transportprotokoll-Konfigurationen sowie spezialisierten PDU-Typen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation»</code> mit dem Tag <code>vh.latestBindingTime = postBuild</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>XcpPdu</code>: Spezialisierte XCP-PDU, spezialisiert <code>IPdu</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>XcpPdu</code> wird als Spezialisierung von <code>IPdu</code> modelliert, wodurch sie die Eigenschaften regulärer I-PDUs erbt, jedoch für Mess- und Kalibrierungszwecke über XCP dient.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li><code>XcpPdu</code> erbt als direkte Spezialisierung von <code>IPdu</code> alle Assoziationen und Attribute der Interaktions-PDU-Schicht.\n</li><li>Das Attribut/Tag für die Bindungszeit lautet standardisiert in Kleinschreibung <code>vh.latestBindingTime = postBuild</code>.\n</li><li>Sämtliche Spezialisierungen von <code>FibexElement</code> sind erstklassige <code>PackageableElement</code>-Objekte und können modular in ARXML-Paketen verwaltet werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e58d6c64889dfac1", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Releases R4.2.2, R4.3.1).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung sowie Netzwerkmanagement- und Transportprotokoll-Konfigurationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation»</code> mit dem Tag <code>vh.latestBindingTime = postBuild</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>IPdu</code> und <code>NmPdu</code> trennen standardmäßige Nutzdatenübertragung von Netzwerkmanagement-Botschaften auf PDU-Ebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Pdu</code> sind ausschließlich <code>IPdu</code> und <code>NmPdu</code> als direkte Spezialisierungen abgebildet.\n</li><li>Das Tag für die Bindungszeit an der Assoziation <code>+fibexElement</code> lautet <code>vh.latestBindingTime = postBuild</code>.\n</li><li>Alle Spezialisierungen von <code>FibexElement</code> sind als vollwertige <code>PackageableElement</code>-Objekte modular in ARXML-Paketen persistierbar.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-19a9043b5b2c7d58", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Releases R4.2.2, R4.3.1).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung sowie Netzwerkmanagement- und Transportprotokoll-Konfigurationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation»</code> mit dem Tag <code>vh.latestBindingTime = postBuild</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>IPdu</code> und <code>NmPdu</code> trennen standardmäßige Nutzdatenübertragung von Netzwerkmanagement-Botschaften auf PDU-Ebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Pdu</code> sind ausschließlich <code>IPdu</code> und <code>NmPdu</code> als direkte Spezialisierungen abgebildet.\n</li><li>Das Tag für die Bindungszeit an der Assoziation <code>+fibexElement</code> lautet <code>vh.latestBindingTime = postBuild</code>.\n</li><li>Alle Spezialisierungen von <code>FibexElement</code> sind als vollwertige <code>PackageableElement</code>-Objekte modular in ARXML-Paketen persistierbar.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-92a0390fd21bbc70", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Releases R4.2.2, R4.3.1).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung sowie Netzwerkmanagement- und Transportprotokoll-Konfigurationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation»</code> mit den Tags <code>vh.latestBindingTime = postBuild</code> und <code>mmt.RestrictToStandards = CP,AP</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>IPdu</code> und <code>NmPdu</code> trennen standardmäßige Nutzdatenübertragung von Netzwerkmanagement-Botschaften auf PDU-Ebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Pdu</code> sind ausschließlich <code>IPdu</code> und <code>NmPdu</code> als direkte Spezialisierungen abgebildet.\n</li><li>Die Bindungszeit an der Assoziation <code>+fibexElement</code> ist über <code>vh.latestBindingTime = postBuild</code> festgelegt; die Anwendbarkeit ist über <code>mmt.RestrictToStandards = CP,AP</code> auf Classic Platform und Adaptive Platform beschränkt.\n</li><li>Alle Spezialisierungen von <code>FibexElement</code> sind als vollwertige <code>PackageableElement</code>-Objekte modular in ARXML-Paketen persistierbar.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a8aabce27d5b827e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Releases R4.2.2, R4.3.1).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung sowie Netzwerkmanagement- und Transportprotokoll-Konfigurationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation,atpSplitable»</code> mit den Tags <code>vh.latestBindingTime = postBuild</code> und <code>mmt.RestrictToStandards = CP,AP</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>IPdu</code> und <code>NmPdu</code> trennen standardmäßige Nutzdatenübertragung von Netzwerkmanagement-Botschaften auf PDU-Ebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Pdu</code> sind ausschließlich <code>IPdu</code> und <code>NmPdu</code> als direkte Spezialisierungen abgebildet.\n</li><li>Die Assoziation <code>+fibexElement</code> ist splitbar (<code>«atpSplitable»</code>), sodass Fibex-Elemente eines Systems über mehrere ARXML-Dateien bzw. Pakete verteilt definiert und zusammengeführt werden können.\n</li><li>Die Bindungszeit an der Assoziation <code>+fibexElement</code> ist über <code>vh.latestBindingTime = postBuild</code> festgelegt; die Anwendbarkeit ist über <code>mmt.RestrictToStandards = CP,AP</code> auf Classic Platform und Adaptive Platform beschränkt.\n</li><li>Alle Spezialisierungen von <code>FibexElement</code> sind als vollwertige <code>PackageableElement</code>-Objekte modular in ARXML-Paketen persistierbar.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4a5322b475dc832d", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Releases R4.2.2, R4.3.1).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung sowie Netzwerkmanagement- und Transportprotokoll-Konfigurationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code>, <code>AtpStructureElement</code> und <code>UploadableDesignElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation,atpSplitable»</code> mit den Tags <code>vh.latestBindingTime = postBuild</code> und <code>mmt.RestrictToStandards = CP,AP</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, typisiert als <code>UploadableDesignElement</code> und annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units, typisiert als <code>UploadableDesignElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>IPdu</code> und <code>NmPdu</code> trennen standardmäßige Nutzdatenübertragung von Netzwerkmanagement-Botschaften auf PDU-Ebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Pdu</code> sind ausschließlich <code>IPdu</code> und <code>NmPdu</code> als direkte Spezialisierungen abgebildet.\n</li><li><code>System</code> sowie die Metaklassen <code>CommunicationCluster</code>, <code>ISignal</code>, <code>ISignalGroup</code>, <code>NmConfig</code> und <code>Pdu</code> implementieren <code>UploadableDesignElement</code>, was deren Identifikation und separate Handhabung in Update- und Upload-Design-Workflows ermöglicht.\n</li><li>Die Assoziation <code>+fibexElement</code> ist splitbar (<code>«atpSplitable»</code>), sodass Fibex-Elemente eines Systems über mehrere ARXML-Dateien bzw. Pakete verteilt definiert und zusammengeführt werden können.\n</li><li>Die Bindungszeit an der Assoziation <code>+fibexElement</code> ist über <code>vh.latestBindingTime = postBuild</code> festgelegt; die Anwendbarkeit ist über <code>mmt.RestrictToStandards = CP,AP</code> auf Classic Platform und Adaptive Platform beschränkt.\n</li><li>Alle Spezialisierungen von <code>FibexElement</code> sind als vollwertige <code>PackageableElement</code>-Objekte modular in ARXML-Paketen persistierbar.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7b214558b86b9ed6", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Releases R4.2.2, R4.3.1).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung sowie Netzwerkmanagement- und Transportprotokoll-Konfigurationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code>, <code>AtpStructureElement</code> und <code>UploadableDesignElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation,atpSplitable»</code> mit den Tags <code>vh.latestBindingTime = postBuild</code> und <code>mmt.RestrictToStandards = CP,AP</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, typisiert als <code>UploadableDesignElement</code> und annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units, typisiert als <code>UploadableDesignElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>IPdu</code> und <code>NmPdu</code> trennen standardmäßige Nutzdatenübertragung von Netzwerkmanagement-Botschaften auf PDU-Ebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Pdu</code> sind ausschließlich <code>IPdu</code> und <code>NmPdu</code> als direkte Spezialisierungen abgebildet.\n</li><li><code>System</code> sowie die Metaklassen <code>CommunicationCluster</code>, <code>ISignal</code>, <code>ISignalGroup</code>, <code>NmConfig</code> und <code>Pdu</code> implementieren <code>UploadableDesignElement</code>, was deren Identifikation und separate Handhabung in Update- und Upload-Design-Workflows ermöglicht.\n</li><li>Die Assoziation <code>+fibexElement</code> ist splitbar (<code>«atpSplitable»</code>), sodass Fibex-Elemente eines Systems über mehrere ARXML-Dateien bzw. Pakete verteilt definiert und zusammengeführt werden können.\n</li><li>Die Bindungszeit an der Assoziation <code>+fibexElement</code> ist über <code>vh.latestBindingTime = postBuild</code> festgelegt; die Anwendbarkeit ist über <code>mmt.RestrictToStandards = CP,AP</code> auf Classic Platform und Adaptive Platform beschränkt.\n</li><li>Alle Spezialisierungen von <code>FibexElement</code> sind als vollwertige <code>PackageableElement</code>-Objekte modular in ARXML-Paketen persistierbar.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ad9e76c7717ab2b5", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm aus dem AUTOSAR System Template (Releases R4.2.2, R4.3.1).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Kernentitäten (<code>FibexElement</code>) und deren semantische Integration in das AUTOSAR-Systemmodell unter Berücksichtigung von Variantenbildung. Das Diagramm spezifiziert Metaklassen zur standardisierten Beschreibung von Netzwerk-Topologie, Kommunikationsmatrix, Signal- und PDU-Gruppierung sowie Netzwerkmanagement- und Transportprotokoll-Konfigurationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelelement:</strong>\n<ul class=\"fig-list\"><li><code>System</code>: Repräsentiert das Gesamtsystem, typisiert als <code>ARElement</code>, <code>AtpStructureElement</code> und <code>UploadableDesignElement</code>.\n</li><li><strong>Beziehung:</strong> Assoziiert über die Rolle <code>+fibexElement</code> mit Multiplizität <code>*</code> Instanzen von <code>FibexElement</code>. Die Beziehung trägt das Stereotyp <code>«atpVariation,atpSplitable»</code> mit den Tags <code>vh.latestBindingTime = postBuild</code> und <code>mmt.RestrictToStandards = CP,AP</code>.\n</li></ul>\n</li><li><strong>Abstrakte Basisklasse:</strong>\n<ul class=\"fig-list\"><li><code>FibexElement</code>: Abstrakte Metaklasse, spezialisiert <code>PackageableElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>FibexElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code>: Kommunikationsnetzwerk/Cluster, typisiert als <code>UploadableDesignElement</code> und annotiert mit <code>«atpVariation»</code>.\n</li><li><code>EcuInstance</code>: Physische Steuergeräte-Instanz.\n</li><li><code>Gateway</code>: Modellierung von Gateway-Funktionalität.\n</li><li><code>ISignalIPduGroup</code>: Bündelung von Signal-I-PDUs zur Laufzeitsteuerung.\n</li><li><code>PdurIPduGroup</code>: Bündelung von PduR-Routingpfaden.\n</li><li><code>ISignal</code>: Interaktionssignal auf Systemebene, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>ISignalGroup</code>: Bündelung logisch zusammengehöriger Signale, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>Frame</code>: Protokollrahmen auf dem Übertragungsmedium.\n</li><li><code>NmConfig</code>: Systemweite Netzwerkmanagement-Konfiguration, typisiert als <code>UploadableDesignElement</code>.\n</li><li><code>TpConfig</code>: Systemweite Transportprotokoll-Konfiguration.\n</li><li><code>Pdu</code>: Abstrakte Metaklasse für Protocol Data Units, typisiert als <code>UploadableDesignElement</code>.\n</li></ul>\n</li><li><strong>Spezialisierungshierarchie unterhalb <code>Pdu</code>:</strong>\n<ul class=\"fig-list\"><li><code>NmPdu</code>: Netzwerkmanagement-PDU (spezialisiert <code>Pdu</code>).\n</li><li><code>IPdu</code>: Interaktions-PDU (spezialisiert <code>Pdu</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entwurfs- und Generierungszeit (Statische Transformation):</strong>\n<ul class=\"fig-list\"><li><strong>Variantenauflösung:</strong> Variantenbildung an <code>+fibexElement</code> und <code>CommunicationCluster</code> erlaubt die Konfiguration alternativer Topologien und Kommunikationsmatrizen bis zur Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>).\n</li><li><strong>Stack-Konfiguration:</strong> <code>NmConfig</code> und <code>TpConfig</code> liefern die strukturierte Datenbasis für die Konfigurationsgeneratoren der BSW-Netzwerk- und Transportmodule.\n</li></ul>\n</li><li><strong>Laufzeit-Relevanz (BSW-Stack):</strong>\n<ul class=\"fig-list\"><li><code>ISignalIPduGroup</code> steuert die zyklische Übertragung im COM-Stack.\n</li><li><code>PdurIPduGroup</code> schaltet Routing-Tabellen-Einträge im <code>PduR</code>.\n</li><li><code>IPdu</code> und <code>NmPdu</code> trennen standardmäßige Nutzdatenübertragung von Netzwerkmanagement-Botschaften auf PDU-Ebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Pdu</code> sind ausschließlich <code>IPdu</code> und <code>NmPdu</code> als direkte Spezialisierungen abgebildet.\n</li><li><code>System</code> sowie die Metaklassen <code>CommunicationCluster</code>, <code>ISignal</code>, <code>ISignalGroup</code>, <code>NmConfig</code> und <code>Pdu</code> implementieren <code>UploadableDesignElement</code>, was deren Identifikation und separate Handhabung in Update- und Upload-Design-Workflows ermöglicht.\n</li><li>Die Assoziation <code>+fibexElement</code> ist splitbar (<code>«atpSplitable»</code>), sodass Fibex-Elemente eines Systems über mehrere ARXML-Dateien bzw. Pakete verteilt definiert und zusammengeführt werden können.\n</li><li>Die Bindungszeit an der Assoziation <code>+fibexElement</code> ist über <code>vh.latestBindingTime = postBuild</code> festgelegt; die Anwendbarkeit ist über <code>mmt.RestrictToStandards = CP,AP</code> auf Classic Platform und Adaptive Platform beschränkt.\n</li><li>Alle Spezialisierungen von <code>FibexElement</code> sind als vollwertige <code>PackageableElement</code>-Objekte modular in ARXML-Paketen persistierbar.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-eaa10cd5e1a21ceb", "to": "FIG-11e7a92424a73887", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-11e7a92424a73887", "to": "FIG-426867045b6d6465", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Fibex4Multiplatform::Gateway</code>: Assoziation <code>+ecu</code> (Kardinalität <code>1</code>) zu <code>CoreTopology::EcuInstance</code> entfernt.\n</li><li><code>CoreCommunication::PdurIPduGroup</code>: Als neue Spezialisierung von <code>FibexElement</code> hinzugefügt.\n</li><li><code>CoreCommunication::Pdu</code>: Unterklassen <code>IPdu</code>, <code>NPdu</code> und <code>NmPdu</code> entfernt; <code>Pdu</code> besitzt keine abgebildeten Spezialisierungen mehr.\n</li></ul>"}, {"from": "FIG-426867045b6d6465", "to": "FIG-2968debec6b6a537", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SystemTemplate::System</code>: Assoziation <code>+fibexElement</code> mit Stereotyp <code>«atpVariation»</code> und Tag <code>Vh.latestBindingTime = PostBuild</code> versehen; <code>AtpStructureElement</code> als zusätzlicher Typ-/Stereotypeintrag im Klassenkopf geführt.\n</li><li><code>PackageableElement::FibexElement</code>: Paketpräfix zu <code>FibexCore::FibexElement</code> präzisiert.\n</li><li><code>CoreTopology::CommunicationCluster</code>: Erhält das Stereotyp <code>«atpVariation»</code>.\n</li><li><code>CoreCommunication::IPduGroup</code>: Ersetzt durch <code>CoreCommunication::ISignalIPduGroup</code>.\n</li><li><code>NetworkManagement::NmConfig</code>: Als neue Spezialisierung von <code>FibexElement</code> hinzugefügt.\n</li><li><code>TransportProtocols::TpConfig</code>: Als neue Spezialisierung von <code>FibexElement</code> hinzugefügt.\n</li><li><code>CoreCommunication::ISignalGroup</code>: Als neue Spezialisierung von <code>FibexElement</code> hinzugefügt.\n</li><li><code>CoreCommunication::Pdu</code>: Hierarchie unterhalb wieder eingefügt mit den Spezialisierungen <code>CoreCommunication::IPdu</code>, <code>CoreCommunication::NmPdu</code> und <code>CoreCommunication::XcpPdu</code>.\n</li></ul>"}, {"from": "FIG-2968debec6b6a537", "to": "FIG-2be62dd9be2e7bfa", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CoreCommunication::XcpPdu</code>: Spezialisiert nun <code>IPdu</code> statt direkt <code>Pdu</code>.\n</li><li>Paketpräfixe (<code>SystemTemplate::</code>, <code>FibexCore::</code>, <code>CoreTopology::</code>, <code>CoreCommunication::</code>, <code>Fibex4Multiplatform::</code>, <code>NetworkManagement::</code>, <code>TransportProtocols::</code>) bei allen Elementnamen im Diagramm entfernt (redaktionelle Vereinfachung der Notation).\n</li><li><code>vh.latestBindingTime = postBuild</code>: Schreibweise der Tag-Definition von PascalCase auf camelCase angepasst.\n</li></ul>"}, {"from": "FIG-2be62dd9be2e7bfa", "to": "FIG-e58d6c64889dfac1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>XcpPdu</code>: Metaklasse als Spezialisierung von <code>IPdu</code> vollständig entfernt.\n</li></ul>"}, {"from": "FIG-e58d6c64889dfac1", "to": "FIG-19a9043b5b2c7d58", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-19a9043b5b2c7d58", "to": "FIG-92a0390fd21bbc70", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Assoziation <code>+fibexElement</code>: Am Variation-Notizkommentar («atpVariation» Tags) wurde das Tag <code>mmt.RestrictToStandards = CP,AP</code> ergänzt.\n</li></ul>"}, {"from": "FIG-92a0390fd21bbc70", "to": "FIG-a8aabce27d5b827e", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Assoziation <code>+fibexElement</code>: Das Stereotyp wurde von <code>«atpVariation»</code> zu <code>«atpVariation,atpSplitable»</code> erweitert.\n</li></ul>"}, {"from": "FIG-a8aabce27d5b827e", "to": "FIG-4a5322b475dc832d", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>System</code>: Erweiterung um die Generalisierung bzw. Typisierung <code>UploadableDesignElement</code>.\n</li><li>Metaklassen <code>CommunicationCluster</code>, <code>ISignal</code>, <code>NmConfig</code>, <code>Pdu</code> und <code>ISignalGroup</code>: Jeweils typisiert bzw. erweitert um <code>UploadableDesignElement</code>.\n</li></ul>"}, {"from": "FIG-4a5322b475dc832d", "to": "FIG-7b214558b86b9ed6", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Assoziation <code>+fibexElement</code>: Im Notizkommentar («atpVariation» Tags) wurde die Reihenfolge der Tags vertauscht (<code>mmt.RestrictToStandards = CP,AP</code> steht nun vor <code>vh.latestBindingTime = postBuild</code>).\n</li></ul>"}, {"from": "FIG-7b214558b86b9ed6", "to": "FIG-ad9e76c7717ab2b5", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
